const analysisRaw = $input.first().json;
const prevData = $('Merge All Sources').item.json;

let analysis;

if (analysisRaw.output && typeof analysisRaw.output === 'object' && !Array.isArray(analysisRaw.output)) {
  analysis = analysisRaw.output;
} else {
  let analysisText = analysisRaw.output || analysisRaw.text || '';
  if (!analysisText) {
    throw new Error('Empty AI response: ' + JSON.stringify(analysisRaw));
  }
  const cleaned = analysisText.replace(/```json/gi, '').replace(/```/gi, '').trim();
  try {
    analysis = JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      analysis = JSON.parse(match[0]);
    } else {
      throw new Error('No valid JSON found: ' + cleaned);
    }
  }
}

const sentiment = analysis.sentiment || 'neutral';
const urgency = analysis.urgency || 'medium';
const priority_score = analysis.priority_score || 5;
const requires_human = analysis.requires_human ?? false;
const category = analysis.category || 'general_inquiry';

const should_escalate = requires_human === true ||
  (priority_score >= 7 && sentiment === 'negative') ||
  urgency === 'critical';

// PATTERN: Detailed execution logging — log every decision
console.log(JSON.stringify({
  event: 'analysis_complete',
  timestamp: new Date().toISOString(),
  customer_email: prevData.email,
  source: prevData.source,
  sentiment,
  urgency,
  category,
  priority_score,
  should_escalate,
  requires_human
}));

return [{
  json: {
    ...prevData,
    analysis: {
      sentiment,
      sentiment_score: analysis.sentiment_score ?? 0,
      urgency,
      category,
      key_themes: analysis.key_themes || [],
      summary: analysis.summary || '',
      requires_human,
      priority_score,
      should_escalate
    },
    analysis_timestamp: new Date().toISOString()
  }
}];

const prevData = $('Merge All Sources').item.json;

// PATTERN: Log fallback usage — mentor said fallback failures are unlogged
console.error(JSON.stringify({
  event: 'analysis_fallback_triggered',
  timestamp: new Date().toISOString(),
  customer_email: prevData.email,
  source: prevData.source,
  reason: 'AI Agent failed — using safe defaults'
}));

return [{
  json: {
    ...prevData,
    analysis: {
      sentiment: 'neutral',
      sentiment_score: 0,
      urgency: 'high',
      category: 'general_inquiry',
      key_themes: ['analysis_failed'],
      summary: 'AI analysis failed — requires manual review',
      requires_human: true,
      priority_score: 8,
      should_escalate: true
    },
    analysis_timestamp: new Date().toISOString(),
    analysis_error: true
  }
}];

