const draftRaw = $input.first().json;
const feedbackData = $('Route by Priority').item.json;

let draftText = draftRaw.output || draftRaw.text || '';

if (!draftText || draftText.trim().length < 20) {
  draftText = `Dear ${feedbackData.name},\n\nThank you for reaching out to us. We have received your feedback and our team will respond to you within 24 hours.\n\nBest regards,\nThe Customer Success Team`;
}

// PATTERN: Log draft generation
console.log(JSON.stringify({
  event: 'draft_generated',
  timestamp: new Date().toISOString(),
  customer_email: feedbackData.email,
  draft_length: draftText.trim().length
}));

return [{
  json: {
    ...feedbackData,
    response_draft: draftText.trim(),
    response_subject: `Re: ${feedbackData.subject}`,
    draft_timestamp: new Date().toISOString()
  }
}];

const feedbackData = $('Route by Priority').item.json;

// PATTERN: Log fallback usage
console.error(JSON.stringify({
  event: 'draft_fallback_triggered',
  timestamp: new Date().toISOString(),
  customer_email: feedbackData.email,
  reason: 'AI Draft Agent failed — using generic template'
}));

const fallbackDraft = `Dear ${feedbackData.name},\n\nThank you for taking the time to share your feedback with us. We truly value your input and want to ensure you have the best possible experience.\n\nOur team has received your message and will review it carefully. You can expect a detailed response from us within 24 business hours.\n\nIf your matter is urgent, please don't hesitate to reply to this email directly.\n\nWarm regards,\nThe Customer Success Team`;

return [{
  json: {
    ...feedbackData,
    response_draft: fallbackDraft,
    response_subject: `Re: ${feedbackData.subject}`,
    draft_timestamp: new Date().toISOString(),
    draft_error: true
  }
}];

const feedbackData = $input.first().json;
const retryCount = feedbackData._retry_count || 0;

if (retryCount >= 3) {
  // PATTERN: Log retry exhaustion
  console.error(JSON.stringify({
    event: 'retry_exhausted',
    timestamp: new Date().toISOString(),
    customer_email: feedbackData.email,
    total_retries: retryCount,
    final_status: 'failed_permanent'
  }));

  return [{
    json: {
      ...feedbackData,
      send_status: 'failed_permanent',
      retry_exhausted: true,
      final_retry_count: retryCount
    }
  }];
}

// PATTERN: Log each retry attempt
console.log(JSON.stringify({
  event: 'retry_attempt',
  timestamp: new Date().toISOString(),
  customer_email: feedbackData.email,
  retry_number: retryCount + 1,
  wait_seconds: Math.pow(2, retryCount) * 5
}));

return [{
  json: {
    ...feedbackData,
    _retry_count: retryCount + 1,
    wait_seconds: Math.pow(2, retryCount) * 5,
    send_status: 'retrying',
    retry_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

const name = data.name || 'Unknown';
const nameParts = name.trim().split(' ');
const firstname = nameParts[0] || name;
const lastname = nameParts.slice(1).join(' ') || '';

const hubspotPayload = {
  contact: {
    email: data.email || '',
    firstname,
    lastname,
    feedback_source: data.source || '',
    feedback_sentiment: data.analysis?.sentiment || '',
    feedback_category: data.analysis?.category || '',
    feedback_urgency: data.analysis?.urgency || '',
    last_feedback_date: data.received_at || ''
  },
  note: {
    subject: `Feedback: ${data.subject || ''}`,
    body: `SOURCE: ${data.source}\nSENTIMENT: ${data.analysis?.sentiment} (${data.analysis?.sentiment_score})\nURGENCY: ${data.analysis?.urgency}\nCATEGORY: ${data.analysis?.category}\nPRIORITY: ${data.analysis?.priority_score}/10\nTHEMES: ${(data.analysis?.key_themes || []).join(', ')}\nSUMMARY: ${data.analysis?.summary}\n\nORIGINAL:\n${data.message}\n\nRESPONSE STATUS: ${data.send_status || (data.analysis?.should_escalate ? 'escalated_to_human' : 'auto_sent')}\nANALYSIS ERROR: ${data.analysis_error || false}\nDRAFT ERROR: ${data.draft_error || false}\nRETRY EXHAUSTED: ${data.retry_exhausted || false}`,
    timestamp: Date.now()
  }
};

// PATTERN: Log CRM payload build
console.log(JSON.stringify({
  event: 'crm_payload_built',
  timestamp: new Date().toISOString(),
  customer_email: data.email,
  category: data.analysis?.category,
  should_escalate: data.analysis?.should_escalate
}));

return [{ json: { ...data, hubspot_payload: hubspotPayload } }];

const data = $input.first().json;

// PATTERN: Comprehensive final log — ALL states covered
const logEntry = {
  timestamp: new Date().toISOString(),
  customer_email: data.email,
  customer_name: data.name,
  source: data.source,
  sentiment: data.analysis?.sentiment,
  urgency: data.analysis?.urgency,
  category: data.analysis?.category,
  priority_score: data.analysis?.priority_score,
  should_escalate: data.analysis?.should_escalate,
  requires_human: data.analysis?.requires_human,
  send_status: data.send_status || (data.analysis?.should_escalate ? 'escalated' : 'auto_sent'),
  analysis_error: data.analysis_error || false,
  draft_error: data.draft_error || false,
  retry_exhausted: data.retry_exhausted || false,
  final_retry_count: data.final_retry_count || 0,
  hubspot_updated: true,
  workflow_version: 'v2_mentor_patterns_applied'
};

console.log('WORKFLOW COMPLETE:', JSON.stringify(logEntry, null, 2));

return [{ json: { status: 'complete', log: logEntry } }];
